WITH flattened AS (SELECT id, created_at, coupon_codes, attr_key, attr_value FROM carts LATERAL VIEW EXPLODE(attributes) t AS attr_key, attr_value) SELECT attr_key, COUNT(*) FILTER (WHERE attr_key = 'weight_kg') AS weight_kg_rows, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min, MIN(created_at) AS first_seen FROM flattened GROUP BY attr_key ORDER BY attr_key DESC;
